mapper.select:
SELECT cai.id, cai.orgId, cai.orgName, cai.accountItemId, cai.accountTypeId, cai.accountItemName, cai.type, cai.inservice FROM ( SELECT cai.id, cai.company_id AS orgId, ifnull( cei.abbreviation, '公司' ) AS orgName, cai.account_item_id AS accountItemId, ai.account_type_id AS accountTypeId, ai.`name` AS accountItemName, ai.type, cai.inservice FROM clinic_account_item cai LEFT JOIN account_item ai ON cai.account_item_id = ai.id LEFT JOIN clinic_ext_info cei ON cai.company_id = cei.company_id ) cai
and cai.id = #{queryForm.id}
and cai.accountTypeId = #{queryForm.accountTypeId}
and cai.accountItemId = #{queryForm.accountItemId}
and cai.orgId = #{queryForm.orgId}
and cai.inservice = #{queryForm.inservice}
